const auto scans = rclcpp::SensorDataQoS();                       // keep last 5, best effort, volatile
const auto map = rclcpp::QoS(rclcpp::KeepLast(1)).transient_local();
const auto watched = rclcpp::QoS(rclcpp::KeepLast(10)).deadline(rclcpp::Duration::from_seconds(0.2));

#include <chrono>
#include <format>
#include <iostream>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

using namespace std::chrono_literals;

enum class Reliability { BestEffort, Reliable };
enum class Durability { Volatile, TransientLocal };
enum class Liveliness { Automatic, ManualByTopic };

// A duration policy. Nothing means the value the built-in profiles call "default", which the
// middleware reads as infinite: no deadline at all, or no liveliness lease at all.
using Limit = std::optional<std::chrono::milliseconds>;

struct Profile {
  Reliability reliability = Reliability::Reliable;
  Durability durability = Durability::Volatile;
  Limit deadline = std::nullopt;
  Limit lease = std::nullopt;
  Liveliness liveliness = Liveliness::Automatic;
};

// The checks of rmw_dds_common/src/qos.cpp, in the order that file runs them, each named the way
// rclcpp names it in the warning it logs. Any one of them means no connection at all.
[[nodiscard]] std::vector<std::string> incompatible_policies(const Profile& offered, const Profile& asked) {
  std::vector<std::string> policies;
  if (offered.reliability == Reliability::BestEffort && asked.reliability == Reliability::Reliable) {
    policies.emplace_back("RELIABILITY_QOS_POLICY");
  }
  if (offered.durability == Durability::Volatile && asked.durability == Durability::TransientLocal) {
    policies.emplace_back("DURABILITY_QOS_POLICY");
  }
  const bool deadline_too_short = offered.deadline && asked.deadline && *asked.deadline < *offered.deadline;
  if ((!offered.deadline && asked.deadline) || deadline_too_short) {
    policies.emplace_back("DEADLINE_QOS_POLICY");
  }
  const bool lease_too_short = offered.lease && asked.lease && *asked.lease < *offered.lease;
  if ((offered.liveliness == Liveliness::Automatic && asked.liveliness == Liveliness::ManualByTopic) ||
      (!offered.lease && asked.lease) || lease_too_short) {
    policies.emplace_back("LIVELINESS_QOS_POLICY");
  }
  return policies;
}

struct Case {
  std::string_view offered_text;
  std::string_view asked_text;
  Profile offered;
  Profile asked;
};

[[nodiscard]] std::string result_of(const Case& one) {
  const std::vector<std::string> policies = incompatible_policies(one.offered, one.asked);
  if (policies.empty()) return "connects";
  std::string result;
  for (const std::string& policy : policies) {
    if (!result.empty()) result += ", ";
    result += policy;
  }
  return result;
}

int main() {
  const Profile sensor_data{.reliability = Reliability::BestEffort};
  const Profile plain{};
  const Profile latched{.durability = Durability::TransientLocal};

  const std::vector<Case> cases{
      {.offered_text = "best effort", .asked_text = "reliable", .offered = sensor_data, .asked = plain},
      {.offered_text = "reliable", .asked_text = "best effort", .offered = plain, .asked = sensor_data},
      {.offered_text = "volatile", .asked_text = "transient local", .offered = plain, .asked = latched},
      {.offered_text = "transient local", .asked_text = "volatile", .offered = latched, .asked = plain},
      {.offered_text = "no deadline",
       .asked_text = "deadline 100 ms",
       .offered = plain,
       .asked = Profile{.deadline = 100ms}},
      {.offered_text = "deadline 50 ms",
       .asked_text = "deadline 100 ms",
       .offered = Profile{.deadline = 50ms},
       .asked = Profile{.deadline = 100ms}},
      {.offered_text = "deadline 100 ms",
       .asked_text = "deadline 50 ms",
       .offered = Profile{.deadline = 100ms},
       .asked = Profile{.deadline = 50ms}},
      {.offered_text = "liveliness automatic",
       .asked_text = "liveliness manual by topic",
       .offered = plain,
       .asked = Profile{.liveliness = Liveliness::ManualByTopic}},
      {.offered_text = "best effort, volatile",
       .asked_text = "reliable, transient local",
       .offered = sensor_data,
       .asked = latched},
  };

  std::cout << std::format("{:<22} {:<27} {}\n", "publisher offers", "subscription asks", "result");
  for (const Case& one : cases) {
    std::cout << std::format("{:<22} {:<27} {}\n", one.offered_text, one.asked_text, result_of(one));
  }
}

