#include <chrono>
#include <memory>
#include <string>
#include <string_view>
#include <vector>

#include <rclcpp/rclcpp.hpp>
#include <sensor_msgs/msg/laser_scan.hpp>

using namespace std::chrono_literals;

// The three profiles the exercise compares, in one place so both nodes name them the same way.
[[nodiscard]] rclcpp::QoS qos_named(std::string_view choice) {
  if (choice == "reliable") return rclcpp::QoS(rclcpp::KeepLast(10));
  if (choice == "latched") return rclcpp::QoS(rclcpp::KeepLast(1)).transient_local();
  return rclcpp::SensorDataQoS();
}

class ScanPub : public rclcpp::Node {
 public:
  explicit ScanPub(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("scan_pub", options) {
    const std::string choice = declare_parameter<std::string>("qos", "sensor");
    once_ = choice == "latched";
    publisher_ = create_publisher<sensor_msgs::msg::LaserScan>("scan", qos_named(choice));
    RCLCPP_INFO(get_logger(), "publishing /scan with the %s profile", choice.c_str());
    timer_ = create_timer(100ms, [this] { publish_scan(); });
  }

 private:
  void publish_scan() {
    sensor_msgs::msg::LaserScan scan;
    scan.header.stamp = now();
    scan.header.frame_id = "base_scan";
    scan.range_min = 0.1F;
    scan.range_max = 10.0F;
    scan.ranges = std::vector<float>(360, 1.0F);
    publisher_->publish(scan);
    if (once_) {
      timer_->cancel();  // the latched run publishes one scan and then keeps it for late joiners
      RCLCPP_INFO(get_logger(), "one scan published and kept");
    }
  }

  bool once_ = false;
  rclcpp::Publisher<sensor_msgs::msg::LaserScan>::SharedPtr publisher_;
  rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<ScanPub>());
  rclcpp::shutdown();
}

#include <cstdint>
#include <memory>
#include <string>
#include <string_view>

#include <rclcpp/rclcpp.hpp>
#include <sensor_msgs/msg/laser_scan.hpp>

// The same three profiles as in scan_pub.
[[nodiscard]] rclcpp::QoS qos_named(std::string_view choice) {
  if (choice == "reliable") return rclcpp::QoS(rclcpp::KeepLast(10));
  if (choice == "latched") return rclcpp::QoS(rclcpp::KeepLast(1)).transient_local();
  return rclcpp::SensorDataQoS();
}

// Lets one message in every `every`. No ROS and no clock, so a test drives it with a counter.
class EveryNth {
 public:
  explicit EveryNth(std::int64_t every) : every_(every) {}

  [[nodiscard]] bool passes() { return ++seen_ % every_ == 1 || every_ == 1; }

 private:
  std::int64_t every_;
  std::int64_t seen_ = 0;
};

class ScanSub : public rclcpp::Node {
 public:
  explicit ScanSub(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("scan_sub", options) {
    const std::string choice = declare_parameter<std::string>("qos", "sensor");

    rclcpp::SubscriptionOptions subscription_options;
    subscription_options.event_callbacks.incompatible_qos_callback =
        [this](rclcpp::QOSRequestedIncompatibleQoSInfo& info) {
          RCLCPP_WARN(get_logger(), "incompatible publisher, policy %s, %d in total",
                      rclcpp::qos_policy_name_from_kind(info.last_policy_kind).c_str(), info.total_count);
        };

    subscription_ = create_subscription<sensor_msgs::msg::LaserScan>(
        "scan", qos_named(choice),
        [this](const sensor_msgs::msg::LaserScan& scan) {
          if (throttle_.passes()) {
            RCLCPP_INFO(get_logger(), "scan with %zu beams", scan.ranges.size());
          }
        },
        subscription_options);
    RCLCPP_INFO(get_logger(), "subscribed to /scan with the %s profile", choice.c_str());
  }

 private:
  EveryNth throttle_{10};
  rclcpp::Subscription<sensor_msgs::msg::LaserScan>::SharedPtr subscription_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<ScanSub>());
  rclcpp::shutdown();
}
